#!/usr/bin/env bash
# Generates an exact-numbers GitHub stats card SVG.
#
# Why not github-readme-stats? Its "Total PRs" / "Total Issues" only count
# OPEN items and its default commit count is current-year only. This script
# queries GitHub directly so every number matches the profile's real data:
#   - commits:       REST search, all-time, default branches
#   - PRs / issues:  GraphQL connection totals — every PR/issue authored
#                    by the user in any state (open + closed + merged).
#                    (REST search/issues is NOT used: with an Actions
#                    installation token it only counts open items.)
#   - stars:         sum of stargazers over own non-fork repos (GraphQL)
#   - contributions: contribution calendar total, summed year by year
#                    (GraphQL caps contributionsCollection at 1 year/query)
set -euo pipefail

USERNAME="${GITHUB_REPOSITORY_OWNER:-DeWeWO}"
OUT_FILE="${1:-dist/stats-card.svg}"
mkdir -p "$(dirname "$OUT_FILE")"

# REST search helper -> total_count
search_total() {
  gh api -X GET "search/$1" -f q="$2" -f per_page=1 --jq .total_count
}

TOTAL_COMMITS=$(search_total commits "author:${USERNAME}")
sleep 2

# PR/issue totals use STATS_TOKEN (user PAT) when available so contributions
# to private repositories are counted; otherwise fall back to GITHUB_TOKEN
# (public-only). Everything else stays public-scoped to match the streak card.
PR_ISSUES=$(GH_TOKEN="${STATS_TOKEN:-$GH_TOKEN}" gh api graphql \
  -f query='query($login: String!) { user(login: $login) { pullRequests(first: 1) { totalCount } issues(first: 1) { totalCount } } }' \
  -f login="${USERNAME}" \
  --jq '[.data.user.pullRequests.totalCount, .data.user.issues.totalCount] | @tsv')
TOTAL_PRS=$(cut -f1 <<<"${PR_ISSUES}")
TOTAL_ISSUES=$(cut -f2 <<<"${PR_ISSUES}")

TOTAL_STARS=$(gh api graphql \
  -f query='query($login: String!) { user(login: $login) { repositories(first: 100, ownerAffiliations: OWNER, isFork: false) { nodes { stargazerCount } } } }' \
  -f login="${USERNAME}" \
  --jq '[.data.user.repositories.nodes[].stargazerCount] | add // 0')

CREATED_YEAR=$(gh api "users/${USERNAME}" --jq .created_at | cut -c1-4)
NOW_ISO=$(date -u +%Y-%m-%dT%H:%M:%SZ)
TOTAL_CONTRIBS=0
year="${CREATED_YEAR}"
while [ "${year}" -le "$(date -u +%Y)" ]; do
  from="${year}-01-01T00:00:00Z"
  to="$((year + 1))-01-01T00:00:00Z"
  [ "${to}" \> "${NOW_ISO}" ] && to="${NOW_ISO}"
  count=$(gh api graphql \
    -f query='query($login: String!, $from: DateTime!, $to: DateTime!) { user(login: $login) { contributionsCollection(from: $from, to: $to) { contributionCalendar { totalContributions } } } }' \
    -f login="${USERNAME}" -f from="${from}" -f to="${to}" \
    --jq .data.user.contributionsCollection.contributionCalendar.totalContributions)
  TOTAL_CONTRIBS=$((TOTAL_CONTRIBS + count))
  year=$((year + 1))
  sleep 1
done

DISPLAY_NAME=$(gh api "users/${USERNAME}" --jq '.name // .login')
TITLE="${DISPLAY_NAME}'s GitHub Stats"

# thousands separator
fmt() { sed -e :a -e 's/\(.*[0-9]\)\([0-9]\{3\}\)/\1,\2/;ta' <<<"$1"; }

cat > "${OUT_FILE}" <<SVG
<svg xmlns="http://www.w3.org/2000/svg" width="500" height="195" viewBox="0 0 500 195" font-family="-apple-system,BlinkMacSystemFont,'Segoe UI','Noto Sans',Helvetica,Arial,sans-serif">
  <desc>Exact GitHub stats for ${USERNAME}, generated by GitHub Actions</desc>
  <style>
    .reveal { opacity: 0; animation: slide-in .5s cubic-bezier(.25,.46,.45,.94) forwards; }
    .d0 { animation-delay: 0s } .d1 { animation-delay: .08s } .d2 { animation-delay: .16s }
    .d3 { animation-delay: .24s } .d4 { animation-delay: .32s } .d5 { animation-delay: .4s }
    @keyframes slide-in { from { opacity: 0; transform: translateX(-10px) } to { opacity: 1; transform: translateX(0) } }
  </style>

  <text x="25" y="30" font-size="18" font-weight="600" fill="#38bdf8" class="reveal d0">${TITLE}</text>

  <g class="reveal d1" fill="#58a6ff">
    <path transform="translate(25,53)" d="M8 .25a.75.75 0 0 1 .673.418l1.882 3.815 4.21.612a.75.75 0 0 1 .416 1.279l-3.046 2.97.719 4.192a.751.751 0 0 1-1.088.791L8 12.347l-3.766 1.98a.75.75 0 0 1-1.088-.79l.72-4.194L.818 6.374a.75.75 0 0 1 .416-1.28l4.21-.611L7.327.668A.75.75 0 0 1 8 .25Zm0 2.445L6.615 5.5a.75.75 0 0 1-.564.41l-3.097.45 2.24 2.184a.75.75 0 0 1 .216.664l-.528 3.084 2.769-1.456a.75.75 0 0 1 .698 0l2.77 1.456-.53-3.084a.75.75 0 0 1 .216-.664l2.24-2.183-3.096-.45a.75.75 0 0 1-.564-.41L8 2.694Z"/>
  </g>
  <text x="53" y="66" font-size="14" fill="#8b949e" class="reveal d1">Total Stars</text>
  <text x="478" y="66" font-size="14" font-weight="600" fill="#c9d1d9" text-anchor="end" class="reveal d1">$(fmt "$TOTAL_STARS")</text>

  <g class="reveal d2" fill="#58a6ff">
    <path transform="translate(25,78)" d="M11.93 8.5a4.002 4.002 0 0 1-7.86 0H.75a.75.75 0 0 1 0-1.5h3.32a4.002 4.002 0 0 1 7.86 0h3.32a.75.75 0 0 1 0 1.5Zm-1.43-.75a2.5 2.5 0 1 0-5 0 2.5 2.5 0 0 0 5 0Z"/>
  </g>
  <text x="53" y="91" font-size="14" fill="#8b949e" class="reveal d2">Total Commits</text>
  <text x="478" y="91" font-size="14" font-weight="600" fill="#c9d1d9" text-anchor="end" class="reveal d2">$(fmt "$TOTAL_COMMITS")</text>

  <g class="reveal d3" fill="#58a6ff">
    <path transform="translate(25,103)" d="M1.5 3.25a2.25 2.25 0 1 1 3 2.122v5.256a2.251 2.251 0 1 1-1.5 0V5.372A2.25 2.25 0 0 1 1.5 3.25Zm5.677-.177L9.573.677A.25.25 0 0 1 10 .854V2.5h1A2.5 2.5 0 0 1 13.5 5v5.628a2.251 2.251 0 1 1-1.5 0V5a1 1 0 0 0-1-1h-1v1.646a.25.25 0 0 1-.427.177L7.177 3.427a.25.25 0 0 1 0-.354ZM3.75 2.5a.75.75 0 1 0 0 1.5.75.75 0 0 0 0-1.5Zm0 9.5a.75.75 0 1 0 0 1.5.75.75 0 0 0 0-1.5Zm8.25.75a.75.75 0 1 0 1.5 0 .75.75 0 0 0-1.5 0Z"/>
  </g>
  <text x="53" y="116" font-size="14" fill="#8b949e" class="reveal d3">Pull Requests</text>
  <text x="478" y="116" font-size="14" font-weight="600" fill="#c9d1d9" text-anchor="end" class="reveal d3">$(fmt "$TOTAL_PRS")</text>

  <g class="reveal d4" fill="#58a6ff">
    <path transform="translate(25,128)" d="M8 9.5a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z"/>
    <path transform="translate(25,128)" d="M8 0a8 8 0 1 1 0 16A8 8 0 0 1 8 0ZM1.5 8a6.5 6.5 0 1 0 13 0 6.5 6.5 0 0 0-13 0Z"/>
  </g>
  <text x="53" y="141" font-size="14" fill="#8b949e" class="reveal d4">Issues Opened</text>
  <text x="478" y="141" font-size="14" font-weight="600" fill="#c9d1d9" text-anchor="end" class="reveal d4">$(fmt "$TOTAL_ISSUES")</text>

  <g class="reveal d5" fill="#58a6ff">
    <path transform="translate(25,153)" d="M1.5 1.75V13.5h13.75a.75.75 0 0 1 0 1.5H.75a.75.75 0 0 1-.75-.75V1.75a.75.75 0 0 1 1.5 0Zm14.28 2.53-5.25 5.25a.75.75 0 0 1-1.06 0L7 7.06 4.28 9.78a.751.751 0 0 1-1.042-.018.751.751 0 0 1-.018-1.042l3.25-3.25a.75.75 0 0 1 1.06 0L10 7.94l4.72-4.72a.751.751 0 0 1 1.042.018.751.751 0 0 1 .018 1.042Z"/>
  </g>
  <text x="53" y="166" font-size="14" fill="#8b949e" class="reveal d5">Total Contributions</text>
  <text x="478" y="166" font-size="14" font-weight="600" fill="#c9d1d9" text-anchor="end" class="reveal d5">$(fmt "$TOTAL_CONTRIBS")</text>
</svg>
SVG

echo "stats-card: commits=${TOTAL_COMMITS} prs=${TOTAL_PRS} issues=${TOTAL_ISSUES} stars=${TOTAL_STARS} contributions=${TOTAL_CONTRIBS} -> ${OUT_FILE}"
